//! Generates the shells' wire code from the core's Rust types: the Kotlin wire
//! types (rules in `kotlin.rs`) and the bridge (`bridge.rs`, from the op table).
//! `cargo run -p wiregen` writes every [`Output`]; `-- --verify` and the test
//! below fail when a committed file is not what the Rust types generate.

use std::path::{Path, PathBuf};

mod bridge;
mod kotlin;

pub const HEADER: &str =
    "// Generated by shared/wiregen; do not edit. Regenerate: cargo run -p wiregen";

pub struct Output {
    /// Relative to the repository root.
    pub path: &'static str,
    pub contents: String,
}

pub fn outputs() -> Vec<Output> {
    let mut out = vec![kotlin::wire_types()];
    out.extend(bridge::outputs());
    out
}

pub fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// The generated files whose committed contents differ, by path.
pub fn stale() -> Vec<&'static str> {
    let root = repo_root();
    outputs()
        .into_iter()
        .filter(|o| std::fs::read_to_string(root.join(o.path)).ok().as_ref() != Some(&o.contents))
        .map(|o| o.path)
        .collect()
}

#[cfg(test)]
mod tests {
    #[test]
    fn generated_files_are_current() {
        let stale = super::stale();
        assert!(
            stale.is_empty(),
            "generated files out of date, run `cargo run -p wiregen`: {stale:?}"
        );
    }
}
